import sys

def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return

    n, q = map(int, first)
    active = {}
    answers = []

    for _ in range(q):
        p = input().split()

        if p[0] == b'+':
            eid, u, v = map(int, p[1:])
            active[eid] = (u, v)

        elif p[0] == b'-':
            eid = int(p[1])
            del active[eid]

        else:
            s, t = map(int, p[1:])
            graph = [[] for _ in range(n + 1)]

            for u, v in active.values():
                graph[u].append(v)
                graph[v].append(u)

            seen = {s}
            stack = [s]

            while stack:
                x = stack.pop()
                for y in graph[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)

            answers.append("YES" if t in seen else "NO")

    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    solve()
